/**
 * Puts a page back where the reader left it when they come back to it with
 * Back or Forward (the browser's arrows, Android's back key, an iPhone's
 * swipe), and leaves every other arrival at the top.
 *
 * The browser tries to do this itself and cannot, here: a screen's content
 * comes from IndexedDB, and some of it (the plan on Settings) from the
 * network, a few frames after the page is back, so at the moment the
 * browser restores the page is too short to scroll that far and the reader
 * lands somewhere above where they were (tester feedback, 2026-10-08).
 *
 * So the position is kept per history entry, in memory, and laid back as
 * soon as the page is tall enough to hold it. It gives up when the reader
 * scrolls or touches first — their move wins — or after `GIVE_UP_MS`,
 * when whatever was going to arrive has arrived.
 *
 * The notebook does not use this: it keeps more than a position and puts
 * a row back rather than a pixel offset (features/notebook/placeMemory.ts).
 */
import { useLayoutEffect } from 'react';
import { NavigationType, useLocation, useNavigationType } from 'react-router-dom';

/**
 * How long a returning page waits to grow tall enough. Local reads land in
 * a few frames and the network ones in well under this; past it, a page
 * that is still short has become a different page.
 */
const GIVE_UP_MS = 1500;

const positions = new Map<string, number>();

/** For tests: forget every position. */
export function forgetScrollPositions(): void {
  positions.clear();
}

/** Keeps this screen's scroll position for a return by Back or Forward. */
export function useKeepScroll(enabled = true): void {
  const { key } = useLocation();
  const navigationType = useNavigationType();

  useLayoutEffect(() => {
    if (!enabled) return;
    const target = navigationType === NavigationType.Pop ? positions.get(key) : undefined;
    let settled = target === undefined || target <= 0;
    const cleanups: (() => void)[] = [];
    const stop = (): void => {
      settled = true;
      for (const cleanup of cleanups.splice(0)) cleanup();
    };

    if (!settled && target !== undefined) {
      const place = (): void => {
        if (settled) return;
        const room = document.documentElement.scrollHeight - window.innerHeight;
        if (room < target) return;
        window.scrollTo({ top: target, behavior: 'instant' });
        stop();
      };
      // The reader moving first wins.
      const yield_ = (): void => {
        stop();
      };
      for (const name of ['wheel', 'touchstart', 'keydown', 'pointerdown'] as const) {
        window.addEventListener(name, yield_, { passive: true, once: true });
        cleanups.push(() => {
          window.removeEventListener(name, yield_);
        });
      }
      if (typeof ResizeObserver !== 'undefined') {
        const observer = new ResizeObserver(place);
        observer.observe(document.body);
        cleanups.push(() => {
          observer.disconnect();
        });
      }
      const timer = window.setTimeout(() => {
        // Out of time: as far down as the page now goes.
        if (!settled) window.scrollTo({ top: target, behavior: 'instant' });
        stop();
      }, GIVE_UP_MS);
      cleanups.push(() => {
        window.clearTimeout(timer);
      });
      place();
    }

    return () => {
      stop();
      // Leaving: the page is still laid out as the reader left it.
      positions.set(key, window.scrollY);
    };
  }, [enabled, key, navigationType]);
}
